Command `cat > /tmp/check_size2.c << 'EOF'
#include <stdio.h>
#include <stdint.h>
#include <netinet/in.h>

#pragma pack(push, 1)
struct proxy_header_v2_packed {
    uint8_t sig[12];
    uint8_t cmd_ver;
    uint8_t fam;
    uint16_t len;
    union {
        struct {
            uint32_t src_addr;
            uint32_t dst_addr;
            uint16_t src_port;
            uint16_t dst_port;
        } ip4;
        struct {
            struct in6_addr src_addr;
            struct in6_addr dst_addr;
            uint16_t src_port;
            uint16_t dst_port;
        } ip6;
    } addr;
} __attribute__((packed));
#pragma pack(pop)

int main() {
    printf("sizeof(packed) = %zu\n", sizeof(struct proxy_header_v2_packed));
    printf("sizeof(regular) = %zu\n", sizeof(struct proxy_header_v2));
    return 0;
}
EOF
gcc -o /tmp/check_size2 /tmp/check_size2.c && /tmp/check_size2` executed with exit code 1.

